    }

    @Test
    void notifiersOnConfirmationAndCancellation() {
        Reservation confirmed = reservation(DELUXE, 7, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD).confirm();
        List<Message> sent = Notifiers.standard().stream()
